import { useCallback, useEffect, useRef, useState } from 'react';
import { ttsLocaleOf, type LanguageCode } from '@lexpad/core';
import { platform } from './platform/index.js';
import { SpeechDenied } from './platform/types.js';

/**
 * Saying a word instead of typing it.
 *
 * The engine behind this differs by platform and the app must not know
 * which: the browser's own recogniser on the web, the operating system's
 * inside the shells. That distinction is not academic — Android's web view
 * exposes a recogniser with nothing behind it, so the first version of this
 * looked ready, failed like a refused microphone, and told people to change
 * a setting in a browser they were not using.
 *
 * The one thing every engine needs from us is the language, and a notebook
 * already knows it. A single word out of context is the hardest thing a
 * recogniser is ever asked for; telling it "this will be Persian" turns a
 * guess into a good guess.
 *
 * What it will not do is save anything. The result lands in the field as a
 * draft, to be read and corrected before it becomes a word.
 */

/** What the microphone is doing. */
export type Dictation =
  | { state: 'checking' }
  | { state: 'unsupported' }
  | { state: 'idle'; start: () => void }
  | { state: 'listening'; heard: string; stop: () => void }
  | { state: 'denied'; start: () => void }
  | { state: 'failed'; start: () => void };

/**
 * Listens in one language and hands back what it heard.
 *
 * `onHeard` is called with the final text, once, when the recogniser
 * settles. Interim words appear in `heard` while somebody is still talking,
 * so the button shows it is working rather than looking frozen.
 */
export function useDictation(lang: LanguageCode, onHeard: (text: string) => void): Dictation {
  const [able, setAble] = useState<boolean | undefined>(undefined);
  const [state, setState] = useState<'idle' | 'listening' | 'denied' | 'failed'>('idle');
  const [heard, setHeard] = useState('');
  const handler = useRef(onHeard);
  useEffect(() => {
    handler.current = onHeard;
  }, [onHeard]);

  // Asked once, on mount. A recogniser that exists but cannot run is the
  // worst of the three states, so the button waits for a real answer rather
  // than assuming one.
  useEffect(() => {
    let live = true;
    void platform.speech
      .available()
      .then((yes) => {
        if (live) setAble(yes);
      })
      .catch(() => {
        if (live) setAble(false);
      });
    return () => {
      live = false;
    };
  }, []);

  // Nothing should keep listening after the sheet that opened it has gone.
  useEffect(
    () => () => {
      platform.speech.stop();
    },
    [],
  );

  const stop = useCallback(() => {
    platform.speech.stop();
  }, []);

  const start = useCallback(() => {
    setHeard('');
    setState('listening');
    platform.speech
      .listen(ttsLocaleOf(lang), setHeard)
      .then((text) => {
        setState('idle');
        setHeard('');
        if (text !== '') handler.current(text);
      })
      .catch((cause: unknown) => {
        setHeard('');
        setState(cause instanceof SpeechDenied ? 'denied' : 'failed');
      });
  }, [lang]);

  if (able === undefined) return { state: 'checking' };
  if (!able) return { state: 'unsupported' };
  if (state === 'listening') return { state: 'listening', heard, stop };
  return { state, start };
}
