import { useEffect } from 'react';
import { createPortal } from 'react-dom';
import { type LanguageCode } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { useDictation } from '@/lib/useDictation.js';
import { platform } from '@/lib/platform/index.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import styles from './VoiceButton.module.css';

/**
 * Saying a word instead of typing it.
 *
 * Listening is a moment, not a state of a button. A microphone that only
 * changes colour leaves somebody staring at a text field wondering whether
 * the phone is hearing them — so while it listens the screen says so, in
 * the middle, at a size that can be read at arm's length, and gets out of
 * the way the instant it has a word.
 *
 * It listens in the notebook's own language, and it never saves: what it
 * hears lands in the field as a draft to be read and corrected, because the
 * learner is the one person who cannot spot the error afterwards.
 *
 * Where a device cannot listen — Firefox, a phone with no recogniser — the
 * button is drawn disabled and says why rather than vanishing. A control
 * that is missing looks like a bug; one that explains itself is an answer.
 *
 * Where the plan does not include it, the button stays and carries a lock:
 * tapping it says what it is rather than doing nothing. What a device
 * cannot do comes first, though — offering Pro for something that would
 * still not work afterwards would be a lie.
 */
export function VoiceButton({
  lang,
  onHeard,
  onProblem,
  locked = false,
  onLocked,
  className,
}: {
  /** The language to listen in: the notebook's, not the browser's. */
  lang: LanguageCode;
  onHeard: (text: string) => void;
  /**
   * A refusal or a failure, for the caller to show in its own layout.
   * Reported rather than rendered here: this button lives inside a text
   * field's row, and a paragraph in that row would squeeze the field.
   */
  onProblem: (message: string) => void;
  /** Whether this account may use it at all. */
  locked?: boolean;
  /** Tapped while locked. The caller owns what to offer. */
  onLocked?: (() => void) | undefined;
  className?: string | undefined;
}): React.JSX.Element {
  const dictation = useDictation(lang, (text) => {
    platform.haptics.success();
    onHeard(text);
  });
  const language = LANGUAGE_NAMES[lang];
  // A message about browser settings inside an app is nonsense, and it is
  // what shipped: the shells have no browser to send anybody to.
  const inApp = platform.env.embedded;

  const problem =
    dictation.state === 'denied'
      ? inApp
        ? t('voice.deniedApp')
        : t('voice.deniedWeb')
      : dictation.state === 'failed'
        ? t('voice.failed')
        : '';

  useEffect(() => {
    if (problem !== '') onProblem(problem);
    // onProblem is called once per transition into a problem state; the
    // caller owns how long it stays on screen.
  }, [problem, onProblem]);

  if (dictation.state === 'checking') {
    // Drawn, disabled and silent while the device answers whether it can
    // listen. A button that appears ready and then fails is worse than one
    // that takes a moment.
    return (
      <button type="button" className={cx(styles.mic, className)} disabled aria-hidden="true">
        <Icon name="mic" size={20} weight={2} />
      </button>
    );
  }

  if (dictation.state === 'unsupported') {
    const cannot = inApp ? t('voice.unsupportedApp') : t('voice.unsupportedWeb');
    return (
      <button type="button" className={cx(styles.mic, className)} disabled title={cannot}>
        <Icon name="mic" size={20} weight={2} />
        <span className="sr-only">{cannot}</span>
      </button>
    );
  }

  // After the two states a device decides, and before listening: a lock
  // on a button that would not have worked anyway is the wrong answer.
  if (locked) {
    // A lock rather than a disabled control: this one does something when
    // it is tapped, and what it does is explain itself.
    return (
      <button
        type="button"
        className={cx(styles.mic, styles.micLocked, className)}
        aria-label={t('voice.pro')}
        onClick={() => {
          onLocked?.();
        }}
      >
        <Icon name="mic" size={20} weight={2} />
        <span className={styles.lock} aria-hidden="true">
          <Icon name="lock" size={11} weight={2.5} />
        </span>
      </button>
    );
  }

  if (dictation.state === 'listening') {
    // While the overlay is up it owns stopping. The button underneath it is
    // covered and unreachable, so it is drawn rather than offered: two
    // controls that both say "stop listening" is one control too many, for
    // a screen reader as much as for anybody else.
    return (
      <>
        <span className={cx(styles.mic, styles.micOn, className)} aria-hidden="true">
          <Icon name="mic" size={20} weight={2} />
        </span>
        <Listening language={language} heard={dictation.heard} onStop={dictation.stop} />
      </>
    );
  }

  const start = dictation.start;
  return (
    <button
      type="button"
      className={cx(styles.mic, className)}
      aria-label={t('voice.speak', { language })}
      onClick={() => {
        platform.haptics.correct();
        start();
      }}
    >
      <Icon name="mic" size={20} weight={2} />
    </button>
  );
}

/**
 * The listening moment, over everything else.
 *
 * In a portal on `body` rather than in place: it has to sit above the sheet
 * that opened it, and a fixed position inside an animated sheet anchors to
 * the sheet rather than to the screen.
 */
function Listening({
  language,
  heard,
  onStop,
}: {
  language: string;
  heard: string;
  onStop: () => void;
}): React.JSX.Element {
  // Escape stops it, like every other overlay in the app.
  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') onStop();
    };
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  }, [onStop]);

  return createPortal(
    <div
      className={styles.overlay}
      role="dialog"
      aria-modal="true"
      aria-label={t('voice.listeningIn', { language })}
      onClick={onStop}
    >
      <div className={styles.halo}>
        <span className={cx(styles.ring, styles.ring1)} aria-hidden="true" />
        <span className={cx(styles.ring, styles.ring2)} aria-hidden="true" />
        <span className={styles.core} aria-hidden="true">
          <Icon name="mic" size={34} weight={2} />
        </span>
      </div>

      {/* What it heard, as it hears it, where a browser gives interim words.
          The shells do not, so this stays the prompt until the word lands. */}
      <p className={cx(styles.said, heard === '' && styles.saidWaiting)} aria-live="polite" dir="auto">
        {heard === '' ? t('voice.sayNow') : heard}
      </p>
      <p className={styles.inLanguage}>{t('voice.listeningIn', { language })}</p>

      <button type="button" className={styles.stop} onClick={onStop}>
        {t('voice.stop')}
      </button>
      <p className={styles.dismiss}>{t('voice.tapToStop')}</p>
    </div>,
    document.body,
  );
}
